import os
from typing import Any, Dict, List, Optional

import requests


class PerspectiveContentSafetyScorer:
    def __init__(self, api_key: Optional[str] = None, timeout: float = 30.0):
        self.api_key = api_key or os.getenv("PERSPECTIVE_API_KEY")
        if not self.api_key:
            raise ValueError("Missing Perspective API key. Set PERSPECTIVE_API_KEY.")
        self.timeout = timeout
        self.endpoint = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"

    def score(self, text: str, languages: Optional[List[str]] = None) -> Dict[str, Any]:
        if not isinstance(text, str) or not text.strip():
            raise ValueError("text must be a non-empty string")

        requested_attributes = {
            "TOXICITY": {},
            "SEVERE_TOXICITY": {},
            "IDENTITY_ATTACK": {},
            "INSULT": {},
            "PROFANITY": {},
            "THREAT": {},
            "SEXUALLY_EXPLICIT": {},
            "FLIRTATION": {},
        }

        payload: Dict[str, Any] = {
            "comment": {"text": text},
            "requestedAttributes": requested_attributes,
            "doNotStore": True,
        }
        if languages:
            payload["languages"] = languages

        params = {"key": self.api_key}
        resp = requests.post(self.endpoint, params=params, json=payload, timeout=self.timeout)
        resp.raise_for_status()
        data = resp.json()

        attribute_scores: Dict[str, float] = {}
        attribute_spans: Dict[str, Dict[str, float]] = {}
        for attr, details in data.get("attributeScores", {}).items():
            summary = details.get("summaryScore", {})
            attribute_scores[attr] = float(summary.get("value", 0.0))
            span_values = {}
            for i, span in enumerate(details.get("spanScores", [])):
                span_values[f"span_{i}"] = float(span.get("score", {}).get("value", 0.0))
            if span_values:
                attribute_spans[attr] = span_values

        max_score = max(attribute_scores.values()) if attribute_scores else 0.0
        is_unsafe = max_score >= 0.5

        return {
            "provider": "Perspective API",
            "unsafe": is_unsafe,
            "max_score": max_score,
            "attribute_scores": attribute_scores,
            "span_scores": attribute_spans,
            "raw_response": data,
        }
